PRAGMA foreign_keys = ON;
CREATE TABLE competitions (key TEXT PRIMARY KEY, display_name TEXT NOT NULL, provider_league_id TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1);
INSERT INTO competitions (key, display_name, provider_league_id) VALUES ('E0', 'Premier League', '3120672213');
CREATE TABLE fixtures (id TEXT PRIMARY KEY, model_market_id TEXT NOT NULL UNIQUE, provider_fixture_id INTEGER UNIQUE, competition_key TEXT NOT NULL REFERENCES competitions(key), kickoff_utc TEXT NOT NULL, home_team TEXT NOT NULL, away_team TEXT NOT NULL, provider_home_team TEXT, provider_away_team TEXT, status TEXT NOT NULL DEFAULT 'scheduled', match_state TEXT NOT NULL DEFAULT 'unmatched' CHECK (match_state IN ('matched','unmatched')), updated_at TEXT NOT NULL);
CREATE INDEX fixtures_kickoff_idx ON fixtures(kickoff_utc);
CREATE INDEX fixtures_provider_idx ON fixtures(provider_fixture_id);
CREATE TABLE model_predictions (fixture_id TEXT NOT NULL REFERENCES fixtures(id) ON DELETE CASCADE, market TEXT NOT NULL CHECK (market IN ('1x2','ou25')), outcome TEXT NOT NULL CHECK (outcome IN ('home','draw','away','over','under')), probability REAL NOT NULL CHECK (probability >= 0 AND probability <= 1), model_odds REAL, imported_at TEXT NOT NULL, PRIMARY KEY (fixture_id,market,outcome));
CREATE TABLE odds_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, fixture_id TEXT NOT NULL REFERENCES fixtures(id) ON DELETE CASCADE, provider_fixture_id INTEGER NOT NULL, bookmaker TEXT NOT NULL, market TEXT NOT NULL, outcome TEXT NOT NULL, line REAL, decimal_odds REAL NOT NULL, observed_at TEXT NOT NULL, source_price_type TEXT NOT NULL);
CREATE INDEX odds_snapshots_lookup_idx ON odds_snapshots(fixture_id,market,observed_at);
CREATE TABLE comparisons (fixture_id TEXT NOT NULL REFERENCES fixtures(id) ON DELETE CASCADE, market TEXT NOT NULL, outcome TEXT NOT NULL, model_probability REAL NOT NULL, model_odds REAL NOT NULL, market_odds REAL NOT NULL, market_probability REAL NOT NULL, overround REAL NOT NULL, edge REAL NOT NULL, expected_return REAL NOT NULL, classification TEXT NOT NULL, observed_at TEXT NOT NULL, PRIMARY KEY (fixture_id,market,outcome));
CREATE TABLE team_aliases (id INTEGER PRIMARY KEY AUTOINCREMENT, competition_key TEXT NOT NULL REFERENCES competitions(key), canonical_name TEXT NOT NULL, model_name TEXT NOT NULL, provider_name TEXT NOT NULL, provider_team_id INTEGER, UNIQUE(competition_key,model_name,provider_name));
CREATE TABLE site_state (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE sync_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, status TEXT NOT NULL, started_at TEXT NOT NULL, completed_at TEXT, model_fixtures INTEGER NOT NULL DEFAULT 0, provider_fixtures INTEGER NOT NULL DEFAULT 0, matched_fixtures INTEGER NOT NULL DEFAULT 0, odds_requests INTEGER NOT NULL DEFAULT 0, error_message TEXT);
